use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Exp {
    Const(i128),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression under a store.
/// If a variable is missing, its value is defined as -1.
pub fn eval(e: &Exp, store: &HashMap<String, i128>) -> i128 {
    match e {
        Exp::Const(c) => *c,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(a, b) => eval(a, store) + eval(b, store),
        Exp::Mult(a, b) => eval(a, store) * eval(b, store),
    }
}

/// Perform a single-step peephole optimization at the root only
/// (does not recurse into sub-expressions).
pub fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Mult(a, b) => match (&*a, &*b) {
            // absorbing element
            (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),

            // neutral element
            (Exp::Const(1), rhs) => rhs.clone(),
            (lhs, Exp::Const(1)) => lhs.clone(),

            // constant folding
            (Exp::Const(x), Exp::Const(y)) => Exp::Const(x * y),

            _ => Exp::Mult(a, b),
        },

        Exp::Plus(a, b) => match (&*a, &*b) {
            // neutral element
            (Exp::Const(0), rhs) => rhs.clone(),
            (lhs, Exp::Const(0)) => lhs.clone(),

            // constant folding
            (Exp::Const(x), Exp::Const(y)) => Exp::Const(x + y),

            _ => Exp::Plus(a, b),
        },

        other => other,
    }
}

/// "Proof harness" as an executable check:
/// returns true iff evaluation is preserved for this expression and store.
///
/// Note: The original problem asks for a proof; in standard Rust we can't
/// encode formal proofs, but this function computes both sides and checks
/// they are equal for the given inputs.
pub fn optimize_correct(e: Exp, s: &HashMap<String, i128>) -> bool {
    let v1 = eval(&e, s);
    let e_opt = optimize(e);
    let v2 = eval(&e_opt, s);
    v1 == v2
}